            new SettingDef("perf.render_distance", "Graphics", "Geral", "Distância de renderização", "Até onde a câmera enxerga objetos e terreno. Menos distância alivia a placa em ilhas grandes; o céu não é afetado.", "Int", "4000") { Min = 100, Max = 4000, Step = 50, Unit = " m", Keywords = new[] { "alcance", "visão", "câmera", "desempenho" } },
            new SettingDef("graphics.shadow_distance", "Graphics", "Geral", "Distância de sombras", "Até onde o sol desenha sombras. Sombras mais longe custam mais; perto delas ficam nítidas em qualquer valor. A predefinição escolhe um valor, e mudá-lo a torna Personalizada.", "Int", "140") { Min = 20, Max = 400, Step = 5, Unit = " m", PresetControlled = true, Keywords = new[] { "sombra", "sol", "desempenho" } },
            new SettingDef("avatars.max_full", "Graphics", "Geral", "Limite de avatares completos", "Quantos avatares ao mesmo tempo são desenhados com todos os detalhes (corpo e itens personalizados e animações próprias). Os outros aparecem com menos detalhe. Menos avatares completos ajudam em ilhas cheias.", "Int", "10") { Min = 1, Max = 40, Step = 1, Keywords = new[] { "avatares", "pessoas", "multidão", "lod", "desempenho" } },
            new SettingDef("perf.object_lod", "Graphics", "Geral", "LOD de objetos (nível de detalhe)", "Reduz o detalhe de objetos distantes.", "Choice", "high") { Unavailable = "O jogo ainda não tem nível de detalhe para objetos.", Choices = new[] { ("high", "Alto"), ("medium", "Médio"), ("low", "Baixo") } },
            new SettingDef("avatars.lod", "Graphics", "Geral", "LOD de avatares", "A que distância os avatares perdem detalhe: Alto mantém os detalhes mais longe (mais pesado), Baixo reduz mais perto (mais leve).", "Choice", "medium") { Choices = new[] { ("high", "Alto"), ("medium", "Médio"), ("low", "Baixo") }, Keywords = new[] { "detalhe", "avatares", "distância" } },
            new SettingDef("avatars.simplify_distant", "Graphics", "Geral", "Simplificar avatares distantes", "Avatares com corpo personalizado longe de você são desenhados com menos triângulos. Desligado, eles passam direto de completos para o corpo simples.", "Bool", "true") { Keywords = new[] { "lod", "avatares", "triângulos", "desempenho" } },
            new SettingDef("metrics.fps", "Graphics", "Geral", "Mostrar FPS", "Mostra os quadros por segundo sobre o jogo.", "Bool", "false") { Keywords = new[] { "indicador", "quadros", "fps" } },
            new SettingDef("metrics.cpu_gpu", "Graphics", "Geral", "Uso de CPU e GPU", "Mostra o quanto o processador e a placa de vídeo estão ocupados.", "Bool", "false") { Unavailable = "O Godot não informa o uso de CPU e GPU em porcentagem. O tempo de renderização (abaixo) mostra o quanto cada um gasta por quadro." },
            new SettingDef("metrics.memory", "Graphics", "Geral", "Uso de memória (RAM/VRAM)", "Mostra a memória do jogo (RAM) e a de vídeo que ele usa (VRAM).", "Bool", "false") { Keywords = new[] { "ram", "vram", "memória", "indicador" } },
            new SettingDef("metrics.frame_time", "Graphics", "Geral", "Tempo de renderização (ms)", "Mostra, em milissegundos, quanto o processador e a placa de vídeo gastam para desenhar cada quadro.", "Bool", "false") { Keywords = new[] { "ms", "quadro", "indicador", "gpu", "cpu" } },
            new SettingDef("graphics.texture_quality", "Graphics", "Qualidade", "Texturas", "Detalhe das texturas. Média e Baixa usam versões menores das imagens: economizam memória de vídeo e ajudam placas fracas, com imagem mais borrada de perto.", "Choice", "high") { Choices = new[] { ("high", "Alta"), ("medium", "Média"), ("low", "Baixa") }, Keywords = new[] { "textura", "memória de vídeo", "vram", "mipmap" } },
            new SettingDef("graphics.anisotropic", "Graphics", "Qualidade", "Filtragem anisotrópica", "Deixa as texturas nítidas em superfícies vistas de lado, como o chão ao longe. Níveis maiores custam pouco em placas atuais.", "Choice", "2") { Choices = new[] { ("0", "Desligada"), ("2", "2x"), ("4", "4x"), ("8", "8x"), ("16", "16x") }, Keywords = new[] { "filtragem", "nitidez", "chão", "textura" } },
            new SettingDef("graphics.msaa", "Graphics", "Qualidade", "Antialiasing (suavização de bordas)", "MSAA suaviza as bordas dos objetos. Não há FXAA nem TAA de propósito: eles borram o nome sobre os avatares em movimento. Mais amostras custam mais quadros por segundo.", "Choice", "4") { PresetControlled = true, Choices = new[] { ("0", "Desligado"), ("2", "MSAA 2x"), ("4", "MSAA 4x"), ("8", "MSAA 8x") }, Keywords = new[] { "bordas", "serrilhado", "msaa", "suavização" } },
            new SettingDef("graphics.shadows_enabled", "Graphics", "Qualidade", "Sombras do sol", "Liga as sombras que o sol projeta. É um dos efeitos mais pesados; desligado, o mundo fica mais chapado.", "Bool", "true") { PresetControlled = true, Keywords = new[] { "sombra", "sol", "desempenho" } },
            new SettingDef("graphics.shadow_quality", "Graphics", "Qualidade", "Qualidade das sombras", "Suavidade da borda das sombras: Duras são mais leves e serrilhadas; Suaves ficam mais naturais e custam mais.", "Choice", "high") { PresetControlled = true, Choices = new[] { ("hard", "Duras"), ("low", "Suaves: baixa"), ("medium", "Suaves: média"), ("high", "Suaves: alta"), ("ultra", "Suaves: ultra") }, Keywords = new[] { "sombra", "suave", "borda" } },
            new SettingDef("graphics.shadow_cascades", "Graphics", "Qualidade", "Divisões das sombras (cascatas)", "Quantas faixas de distância as sombras do sol usam: mais faixas deixam as sombras nítidas de perto e de longe, mas custam mais.", "Choice", "4") { PresetControlled = true, Choices = new[] { ("1", "1 faixa"), ("2", "2 faixas"), ("4", "4 faixas") }, Keywords = new[] { "cascata", "sombra", "distância" } },
            new SettingDef("graphics.ssao", "Graphics", "Qualidade", "Oclusão ambiente", "Escurece cantos, frestas e a base dos objetos, como acontece na luz de verdade. Dá volume à cena e custa processamento de tela.", "Bool", "true") { PresetControlled = true, Keywords = new[] { "ssao", "oclusão", "cantos", "iluminação" } },
            new SettingDef("graphics.ssao_quality", "Graphics", "Qualidade", "Qualidade da oclusão ambiente", "Precisão do cálculo da oclusão ambiente. Níveis altos são mais suaves e mais pesados.", "Choice", "medium") { PresetControlled = true, Choices = new[] { ("verylow", "Muito baixa"), ("low", "Baixa"), ("medium", "Média"), ("high", "Alta"), ("ultra", "Ultra") }, Keywords = new[] { "ssao", "oclusão" } },
            new SettingDef("graphics.ssil", "Graphics", "Qualidade", "Iluminação indireta de tela", "Faz a luz dos objetos coloridos \"vazar\" para os vizinhos. Só a predefinição Ultra usa; é pesado.", "Bool", "false") { PresetControlled = true, Keywords = new[] { "ssil", "iluminação", "luz indireta" } },
            new SettingDef("graphics.glow", "Graphics", "Qualidade", "Brilho (bloom)", "Halo suave em volta do sol e das luzes fortes.", "Bool", "true") { PresetControlled = true, Keywords = new[] { "bloom", "brilho", "pós-processamento" } },
            new SettingDef("graphics.color_adjust", "Graphics", "Qualidade", "Ajuste de cor", "Realça levemente o contraste e a saturação da imagem final.", "Bool", "true") { PresetControlled = true, Keywords = new[] { "cor", "contraste", "saturação", "pós-processamento" } },
            new SettingDef("graphics.ssr", "Graphics", "Qualidade", "Reflexos de tela", "Superfícies lisas e opacas refletem o que está na tela. Não afeta a água (que é transparente). Custa processamento de tela; as predefinições não mudam isso.", "Bool", "false") { Keywords = new[] { "reflexo", "ssr", "espelho", "iluminação" } },
            new SettingDef("graphics.volumetric", "Graphics", "Qualidade", "Raios de luz (névoa volumétrica)", "Mostra a luz do sol atravessando o ar, com um leve véu de névoa. É pesado em placas fracas; as predefinições não mudam isso.", "Bool", "false") { Keywords = new[] { "volumétrico", "névoa", "raios", "efeitos" } },
            new SettingDef("graphics.fog", "Graphics", "Qualidade", "Neblina do clima", "A névoa de dias nublados, de chuva e de neblina. Desligada, o ar fica limpo em qualquer clima.", "Bool", "true") { Keywords = new[] { "névoa", "neblina", "clima" } },
            new SettingDef("graphics.particles", "Graphics", "Qualidade", "Partículas", "Quantidade de partículas da chuva e dos efeitos dos objetos (fogo, fumaça, faíscas). Efeitos já criados só mudam quando forem criados de novo.", "Choice", "full") { Choices = new[] { ("full", "Todas"), ("medium", "Médias"), ("low", "Poucas"), ("off", "Desligadas") }, Keywords = new[] { "chuva", "fogo", "fumaça", "efeitos" } },
            new SettingDef("graphics.water_waves", "Graphics", "Qualidade", "Ondas da água", "As ondas que movem a superfície do mar. Desligadas, a água fica plana, com o mesmo brilho e espuma.", "Bool", "true") { Keywords = new[] { "água", "mar", "ondas" } },
            new SettingDef("graphics.vegetation", "Graphics", "Qualidade", "Vegetação", "Nível de detalhe de árvores e grama.", "Choice", "high") { Unavailable = "Árvores e grama são objetos criados pelos jogadores; o jogo não tem vegetação própria com níveis de qualidade.", Choices = new[] { ("high", "Alta"), ("medium", "Média"), ("low", "Baixa") } },
            new SettingDef("world.object_distance", "Graphics", "Mundo e avatares", "Distância de visibilidade de objetos", "Objetos mais longe que isto deixam de ser desenhados (a colisão continua). No máximo (1000 m), nenhum é escondido.", "Int", "1000") { Min = 50, Max = 1000, Step = 25, Unit = " m", Keywords = new[] { "objetos", "alcance", "distância", "desempenho" } },
            new SettingDef("world.max_lights", "Graphics", "Mundo e avatares", "Limite de luzes visíveis", "Quantas luzes de objetos ficam acesas ao mesmo tempo. As primeiras a aparecer na ilha acendem; as demais ficam apagadas até que outras sumam. Luzes são caras.", "Int", "16") { Min = 0, Max = 64, Step = 1, Keywords = new[] { "luzes", "iluminação", "objetos" } },
            new SettingDef("world.max_light_shadows", "Graphics", "Mundo e avatares", "Luzes com sombra", "Quantas das luzes acesas projetam sombra. Cada uma custa bastante.", "Int", "4") { Min = 0, Max = 16, Step = 1, Keywords = new[] { "luzes", "sombra" } },
            new SettingDef("avatars.visibility_distance", "Graphics", "Mundo e avatares", "Distância de visibilidade de avatares", "Avatares mais longe que isto deixam de ser desenhados. Mais perto aparecem primeiro simples e ganham detalhe ao chegar perto.", "Int", "120") { Min = 30, Max = 300, Step = 10, Unit = " m", Keywords = new[] { "avatares", "pessoas", "distância", "desempenho" } },
            new SettingDef("avatars.max_reduced", "Graphics", "Mundo e avatares", "Máximo de avatares com detalhe reduzido", "Quantos avatares ao mesmo tempo usam o corpo personalizado simplificado (o degrau entre completo e simples).", "Int", "24") { Min = 0, Max = 60, Step = 1, Keywords = new[] { "avatares", "lod", "multidão" } },
            new SettingDef("avatars.triangle_budget", "Graphics", "Mundo e avatares", "Orçamento de complexidade visual dos avatares", "Quantos milhares de triângulos todos os avatares juntos podem custar. Quando o orçamento acaba, os mais distantes perdem detalhe primeiro.", "Int", "250") { Min = 50, Max = 1000, Step = 50, Unit = " mil triângulos", Keywords = new[] { "triângulos", "avatares", "complexidade", "orçamento", "desempenho" } },
            new SettingDef("avatars.animation_quality", "Graphics", "Mundo e avatares", "Qualidade das animações", "Com que frequência os avatares de detalhe reduzido são animados: Alta anima todo quadro, Normal um a cada dois, Baixa um a cada três. Menos animação alivia o processador em ilhas cheias.", "Choice", "normal") { Choices = new[] { ("high", "Alta"), ("normal", "Normal"), ("low", "Baixa") }, Keywords = new[] { "animação", "avatares", "processador" } },
            new SettingDef("avatars.texture_quality", "Graphics", "Mundo e avatares", "Qualidade das texturas dos avatares", "Detalhe das texturas dos avatares.", "Choice", "high") { Unavailable = "As texturas dos avatares seguem a opção Texturas da aba Qualidade; não há um nível só para avatares.", Choices = new[] { ("high", "Alta"), ("medium", "Média"), ("low", "Baixa") } },
            new SettingDef("perf.auto_quality", "Graphics", "Otimização", "Ajuste automático de desempenho", "Se os quadros por segundo ficarem bem abaixo da meta por cerca de 15 segundos, baixa a predefinição gráfica um nível (no máximo uma vez por minuto) e avisa. Não mexe em uma predefinição Personalizada.", "Bool", "false") { Keywords = new[] { "automático", "desempenho", "fps", "qualidade" } },
            new SettingDef("perf.background_fps", "Graphics", "Otimização", "Redução de qualidade em segundo plano", "Quando a janela do jogo perde o foco, limita os quadros por segundo para economizar energia e calor. Volta ao limite normal ao voltar.", "Choice", "off") { Choices = new[] { ("off", "Desligada"), ("30", "30 FPS"), ("15", "15 FPS"), ("5", "5 FPS") }, Keywords = new[] { "segundo plano", "foco", "economia", "energia" } },
            new SettingDef("perf.shader_cache", "Graphics", "Otimização", "Cache de shaders", "Guarda os shaders já compilados para a próxima abertura.", "Bool", "true") { Unavailable = "O Godot gerencia o cache de shaders sozinho e a escolha só existe na configuração do projeto, não em tempo de execução." },
            new SettingDef("perf.resource_cache", "Graphics", "Otimização", "Tamanho do cache de recursos", "Limite de espaço em disco para modelos e texturas baixados.", "Int", "2048") { Min = 256, Max = 16384, Step = 256, Unit = " MB", Unavailable = "O cache de recursos ainda não tem limite configurável nem remoção dos mais antigos." },
            new SettingDef("perf.preload_assets", "Graphics", "Otimização", "Pré-carregamento de assets", "Baixa antes de precisar os modelos e texturas das ilhas favoritas.", "Bool", "false") { Unavailable = "O jogo carrega os assets quando entra na ilha; não há pré-carregamento de ilhas." },
            new SettingDef("audio.master", "Audio", "Geral", "Volume geral", "Volume de todos os sons do jogo. Zero silencia tudo.", "Float", "1.0") { Min = 0, Max = 1, Step = 0.05, Keywords = new[] { "volume", "som", "mudo", "áudio" } },
        };
    }
